<template><div class="ui-threshold"><header><span>{{label}}</span><UiStatusBadge :status="tone" :label="statusLabel"/></header><div class="ui-threshold__value"><strong class="ui-numeric">{{value}}</strong><small>{{unit}}</small><slot name="trend"/></div><UiProgressBar :value="percent" :tone="progressTone" :show-value="false"/><footer><span>阈值 {{threshold}}{{unit}}</span><span v-if="context">{{context}}</span></footer></div></template>
<script setup lang="ts">import{computed}from'vue';import UiProgressBar from './UiProgressBar.vue';import UiStatusBadge from './UiStatusBadge.vue';const props=withDefaults(defineProps<{label:string;value:number;threshold:number;max?:number;unit?:string;context?:string;inverse?:boolean}>(),{max:100,unit:'',inverse:false});const breached=computed(()=>props.inverse?props.value<props.threshold:props.value>=props.threshold);const near=computed(()=>Math.abs(props.value-props.threshold)/Math.max(props.threshold,1)<.15);const tone=computed(()=>(breached.value?'danger':near.value?'warning':'success'));const statusLabel=computed(()=>(breached.value?'超过阈值':near.value?'接近阈值':'正常'));const progressTone=computed(()=>(tone.value==='danger'?'danger':tone.value==='warning'?'warning':'neutral'));const percent=computed(()=>Math.min(100,Math.max(0,props.value/props.max*100)));</script>
<style scoped>.ui-threshold{display:grid;gap:8px;padding:10px;border:1px solid var(--ui-border-soft);border-radius:var(--ui-radius);background:var(--ui-surface)}.ui-threshold header,.ui-threshold footer,.ui-threshold__value{display:flex;align-items:center;justify-content:space-between;gap:8px}.ui-threshold header>span{color:var(--ui-text-muted);font-size:12px}.ui-threshold__value{justify-content:flex-start}.ui-threshold__value strong{font-size:22px;font-weight:500}.ui-threshold__value small{color:var(--ui-text-soft);font-size:11px}.ui-threshold footer{color:var(--ui-text-soft);font-size:10px}</style>
